package rosemary_and_thyme.models.responses
import kotlinx.serialization.Serializable

/**
 * Result of creating a draft recipe and preparing its direct image uploads.
 *
 * @property recipeId identifier generated by the database for the draft
 * @property uploads temporary upload grants paired with their image identifiers
 */
@Serializable
data class PostRecipeResponse(
    val recipeId: String,
    val uploads: List<ImageUploadResponse>
)

/**
 * Presigned direct-upload grant for one recipe image.
 *
 * @property imageId client-generated identifier of the corresponding image
 * @property uploadUrl temporary R2 PUT URL that accepts `image/png`
 */
@Serializable
data class ImageUploadResponse(
    val imageId: String,
    val uploadUrl: String
)
